from queueing import payload
def submit(owner, enqueue, region=None):
    return enqueue(payload(owner, region))

def payload(owner, region=None):
    if region is None:
        region = "worldwide"
    # validate region
    valid = {"worldwide", "europe", "americas"}
    if region not in valid:
        raise ValueError(f'Invalid region {region!r}. Must be worldwide, europe, or americas.')
    return {"owner": owner, "region": region}

def execute(task, collect):
    # task may have region from payload
    region = task.get("region", "worldwide")
    # legacy records without region already mean worldwide; our validation ensures region present
    return collect(task["owner"], region)

import api
import queueing
import worker

def test_api_submit_default():
    def dummy_enqueue(p):
        return p
    owner = 'test'
    task = api.submit(owner, dummy_enqueue)
    # payload should have region worldwide
    assert 'region' in task
    assert task['region'] == 'worldwide'

def test_api_submit_explicit_worldwide():
    def dummy_enqueue(p):
        return p
    owner = 'test'
    task = api.submit(owner, dummy_enqueue, 'worldwide')
    assert task['region'] == 'worldwide'

def test_queueing_payload_default():
    owner = 'test'
    p = queueing.payload(owner)
    assert p['owner'] == owner
    assert p['region'] == 'worldwide'

def test_queueing_payload_explicit_valid():
    owner = 'test'
    for r in ['worldwide', 'europe', 'americas']:
        p = queueing.payload(owner, r)
        assert p['region'] == r

def test_queueing_payload_invalid():
    owner = 'test'
    try:
        queueing.payload(owner, 'invalid')
        assert False, 'should raise'
    except ValueError as e:
        pass

def test_worker_execute_with_region():
    def dummy_collect(owner, region):
        return f'{owner}:{region}'
    task = {'owner':'test','region':'europe'}
    result = worker.execute(task, dummy_collect)
    assert result == 'test:europe'

def test_worker_execute_legacy_no_region():
    def dummy_collect(owner, region):
        return f'{owner}:{region}'
    # task without region (legacy) should default to worldwide
    task = {'owner':'test'}
    result = worker.execute(task, dummy_collect)
    assert result == 'test:worldwide'

if __name__ == '__main__':
    test_api_submit_default()
    test_api_submit_explicit_worldwide()
    test_queueing_payload_default()
    test_queueing_payload_explicit_valid()
    test_queueing_payload_invalid()
    test_worker_execute_with_region()
    test_worker_execute_legacy_no_region()
    print('All tests passed')
